def is_catchy(sign):
    """Return True when no letter of sign repeats."""
    pass

exercise.solution:
def is_catchy(sign):
    # distinct letters must equal total letters for nothing to repeat
    return len(set(sign)) == len(sign)

exercise.starter:
def shift_letters(text, k):
    """Shift each a-z letter of text forward by k (mod 26)."""
    pass

exercise.solution:
def shift_letters(text, k):
    pieces = []
    for ch in text:
        if 'a' <= ch <= 'z':
            pieces.append(chr((ord(ch) - 97 + k) % 26 + 97))
        else:
            pieces.append(ch)
    return ''.join(pieces)

exercise.starter:
def top_words(text, k):
    """Return the k most frequent words; ties by first appearance."""
    pass

exercise.solution:
def top_words(text, k):
    counts, first_at = {}, {}
    for i, w in enumerate(text.split()):
        if w not in counts:
            counts[w] = 0
            first_at[w] = i
        counts[w] += 1
    ranked = sorted(counts, key=lambda w: (-counts[w], first_at[w]))
    return ranked[:k]

