def sync_point(stream):
    """Return the index completing the first 4 distinct chars, else -1."""
    pass

exercise.solution:
def sync_point(stream):
    for i in range(3, len(stream)):
        if len(set(stream[i - 3:i + 1])) == 4:
            return i
    return -1

exercise.starter:
def dominant_char(log):
    """Return the most frequent character (earliest wins ties), or ''."""
    pass

exercise.solution:
def dominant_char(log):
    if len(log) == 0:
        return ''
    counts = {}
    for ch in log:                       # pass 1: the counts table
        counts[ch] = counts.get(ch, 0) + 1
    best = max(counts.values())
    for ch in log:                       # pass 2: earliest at max count
        if counts[ch] == best:
            return ch
    return ''   # not reached: some character attains the max

exercise.starter:
def column_label(n):
    """Return the spreadsheet label of column n (column 1 is 'A')."""
    pass

exercise.solution:
def column_label(n):
    letters = []
    while n > 0:
        n -= 1                      # shift into the 0-25 digit range
        letters.append(chr(65 + n % 26))
        n //= 26
    return ''.join(reversed(letters))
